use std::io::{self, BufRead};

fn is_valid(line: &str) -> bool {
    let mut stack = Vec::new();

    for bracket in line.bytes() {
        match bracket {
            b'(' | b'[' | b'{' => stack.push(bracket),
            b')' => {
                if stack.pop() != Some(b'(') {
                    return false;
                }
            }
            b']' => {
                if stack.pop() != Some(b'[') {
                    return false;
                }
            }
            b'}' => {
                if stack.pop() != Some(b'{') {
                    return false;
                }
            }
            _ => unreachable!(),
        }
    }

    stack.is_empty()
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();
    let count: usize = lines
        .next()
        .expect("missing line count")
        .expect("failed to read line count")
        .trim()
        .parse()
        .expect("invalid line count");

    let mut output = String::new();
    for index in 0..count {
        let line = lines
            .next()
            .expect("missing bracket line")
            .expect("failed to read bracket line");
        if index > 0 {
            output.push('\n');
        }
        output.push_str(if is_valid(&line) { "valid" } else { "invalid" });
    }

    if count > 0 {
        println!("{output}");
    }
}

