import sys


def compact_ranges(numbers: list[int]) -> str:
    parts: list[str] = []
    index = 0

    while index < len(numbers):
        end = index
        while end + 1 < len(numbers) and numbers[end + 1] == numbers[end] + 1:
            end += 1

        if end - index + 1 >= 3:
            parts.append(f"{numbers[index]}-{numbers[end]}")
        else:
            parts.extend(str(numbers[position]) for position in range(index, end + 1))

        index = end + 1

    return ",".join(parts)


def main() -> None:
    values = sys.stdin.buffer.read().split()
    count = int(values[0])
    numbers = [int(value) for value in values[1 : count + 1]]
    print(compact_ranges(numbers))


if __name__ == "__main__":
    main()

