use std::io::{self, Read};

fn append_run(output: &mut String, start: i128, end: i128, length: usize) {
    if !output.is_empty() {
        output.push(',');
    }

    if length >= 3 {
        output.push_str(&start.to_string());
        output.push('-');
        output.push_str(&end.to_string());
    } else {
        output.push_str(&start.to_string());
        if length == 2 {
            output.push(',');
            output.push_str(&end.to_string());
        }
    }
}

